class StockPrice {
    unordered_map<int, int> prices;
    priority_queue<pair<int, int>> maxHeap;
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> minHeap;
    int latestTimestamp;
public:
    StockPrice() : latestTimestamp(0) {

    }

    void update(int timestamp, int price) {
        prices[timestamp] = price;
        if (timestamp > latestTimestamp) {
            latestTimestamp = timestamp;
        }
        maxHeap.push({price, timestamp});
        minHeap.push({price, timestamp});
    }

    int current() {
        return prices[latestTimestamp];
    }

    int maximum() {
        while (true) {
            auto [p, t] = maxHeap.top();
            if (prices[t] == p) return p;
            maxHeap.pop();
        }
    }

    int minimum() {
        while (true) {
            auto [p, t] = minHeap.top();
            if (prices[t] == p) return p;
            minHeap.pop();
        }
    }
};
